import{_ as i,c as o,o as s,j as a,Y as r,t as n}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"git-revert | x-cmd man (git man1) | Revert some existing commits","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-revert - Revert some existing commits","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-revert | x-cmd man (git man1) | Revert some existing commits"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-revert - Revert some existing commits"}]]},"headers":[],"params":{"isMan":true,"man":"git-revert","category":"git man1","desc":"Revert some existing commits"},"relativePath":"git/man1/git-revert.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-revert.md"},l={class:"visually-hidden"};function c(t,e,g,p,m,d){return s(),o("div",null,[a("h1",l,n(t.$params.man),1),e[0]||(e[0]=r(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-revert - Revert some existing commits</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--[no-]edit] [-n] [-m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parent-number</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [-s] [-S[</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keyid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">commit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (--continue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --skip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --abort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --quit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Given one or more existing commits, revert the changes that the related patches introduce, and record some new commits that record them. This requires your working tree to be clean (no modifications from the HEAD commit).</p><p>Note: <em>git revert</em> is used to record some new commits to reverse the effect of some earlier commits (often only a faulty one). If you want to throw away all uncommitted changes in your working directory, you should see <strong>git-reset</strong>(1), particularly the <strong>--hard</strong> option. If you want to extract specific files as they were in another commit, you should see <strong>git-restore</strong>(1), specifically the <strong>--source</strong> option. Take care with these alternatives as both will discard uncommitted changes in your working directory.</p><p>See &quot;Reset, restore and revert&quot; in <strong>git</strong>(1) for the differences between the three commands.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>&lt;commit&gt;...</p><blockquote><p>Commits to revert. For a more complete list of ways to spell commit names, see <strong>gitrevisions</strong>(7). Sets of commits can also be given but no traversal is done by default, see <strong>git-rev-list</strong>(1) and its <strong>--no-walk</strong> option.</p></blockquote><p>-e, --edit</p><blockquote><p>With this option, <em>git revert</em> will let you edit the commit message prior to committing the revert. This is the default if you run the command from a terminal.</p></blockquote><p>-m parent-number, --mainline parent-number</p><blockquote><p>Usually you cannot revert a merge because you do not know which side of the merge should be considered the mainline. This option specifies the parent number (starting from 1) of the mainline and allows revert to reverse the change relative to the specified parent.</p><p>Reverting a merge commit declares that you will never want the tree changes brought in by the merge. As a result, later merges will only bring in tree changes introduced by commits that are not ancestors of the previously reverted merge. This may or may not be what you want.</p><p>See the <strong>revert-a-faulty-merge How-To</strong>[1] for more details.</p></blockquote><p>--no-edit</p><blockquote><p>With this option, <em>git revert</em> will not start the commit message editor.</p></blockquote><p>--cleanup=&lt;mode&gt;</p><blockquote><p>This option determines how the commit message will be cleaned up before being passed on to the commit machinery. See <strong>git-commit</strong>(1) for more details. In particular, if the <em>&lt;mode&gt;</em> is given a value of <strong>scissors</strong>, scissors will be appended to <strong>MERGE_MSG</strong> before being passed on in the case of a conflict.</p></blockquote><p>-n, --no-commit</p><blockquote><p>Usually the command automatically creates some commits with commit log messages stating which commits were reverted. This flag applies the changes necessary to revert the named commits to your working tree and the index, but does not make the commits. In addition, when this option is used, your index does not have to match the HEAD commit. The revert is done against the beginning state of your index.</p><p>This is useful when reverting more than one commits&#39; effect to your index in a row.</p></blockquote><p>-S[&lt;keyid&gt;], --gpg-sign[=&lt;keyid&gt;], --no-gpg-sign</p><blockquote><p>GPG-sign commits. The <strong>keyid</strong> argument is optional and defaults to the committer identity; if specified, it must be stuck to the option without a space. <strong>--no-gpg-sign</strong> is useful to countermand both <strong>commit.gpgSign</strong> configuration variable, and earlier <strong>--gpg-sign</strong>.</p></blockquote><p>-s, --signoff</p><blockquote><p>Add a <strong>Signed-off-by</strong> trailer at the end of the commit message. See the signoff option in <strong>git-commit</strong>(1) for more information.</p></blockquote><p>--strategy=&lt;strategy&gt;</p><blockquote><p>Use the given merge strategy. Should only be used once. See the MERGE STRATEGIES section in <strong>git-merge</strong>(1) for details.</p></blockquote><p>-X&lt;option&gt;, --strategy-option=&lt;option&gt;</p><blockquote><p>Pass the merge strategy-specific option through to the merge strategy. See <strong>git-merge</strong>(1) for details.</p></blockquote><p>--rerere-autoupdate, --no-rerere-autoupdate</p><blockquote><p>After the rerere mechanism reuses a recorded resolution on the current conflict to update the files in the working tree, allow it to also update the index with the result of resolution. <strong>--no-rerere-autoupdate</strong> is a good way to double-check what <strong>rerere</strong> did and catch potential mismerges, before committing the result to the index with a separate <strong>git add</strong>.</p></blockquote><p>--reference</p><blockquote><p>Instead of starting the body of the log message with &quot;This reverts &lt;full object name of the commit being reverted&gt;.&quot;, refer to the commit using &quot;--pretty=reference&quot; format (cf. <strong>git-log</strong>(1)). The <strong>revert.reference</strong> configuration variable can be used to enable this option by default.</p></blockquote><h2 id="sequencer-subcommands" tabindex="-1">SEQUENCER SUBCOMMANDS <a class="header-anchor" href="#sequencer-subcommands" aria-label="Permalink to &quot;SEQUENCER SUBCOMMANDS&quot;">​</a></h2><p>--continue</p><blockquote><p>Continue the operation in progress using the information in <strong>.git/sequencer</strong>. Can be used to continue after resolving conflicts in a failed cherry-pick or revert.</p></blockquote><p>--skip</p><blockquote><p>Skip the current commit and continue with the rest of the sequence.</p></blockquote><p>--quit</p><blockquote><p>Forget about the current operation in progress. Can be used to clear the sequencer state after a failed cherry-pick or revert.</p></blockquote><p>--abort</p><blockquote><p>Cancel the operation and return to the pre-sequence state.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p><strong>git revert HEAD~3</strong></p><blockquote><p>Revert the changes specified by the fourth last commit in HEAD and create a new commit with the reverted changes.</p></blockquote><p><strong>git revert -n master~5..master~2</strong></p><blockquote><p>Revert the changes done by commits from the fifth last commit in master (included) to the third last commit in master (included), but do not create any commit with the reverted changes. The revert only modifies the working tree and the index.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>revert.reference</p><blockquote><p>Setting this variable to true makes <strong>git revert</strong> behave as if the <strong>--reference</strong> option is given.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-cherry-pick</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: revert-a-faulty-merge How-To</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/howto/revert-a-faulty-merge.html</span></span></code></pre></div>`,59))])}const b=i(h,[["render",c]]);export{k as __pageData,b as default};
